function PatientEHRImport() {
  const [selectedFile, setSelectedFile] = React.useState(null);
  const [previewData, setPreviewData] = React.useState('');

  const handleFileChange = (event) => {
    const file = event.target.files[0];
    setSelectedFile(file);

    const reader = new FileReader();
    reader.onload = (e) => {
      setPreviewData(e.target.result);
    };
    reader.readAsText(file);
  };

  return (
    <div className="max-w-4xl mx-auto p-4 bg-gray-100 rounded shadow">
      <h2 className="text-2xl font-semibold mb-4 text-gray-800">Import Patient EHR</h2>
      <div className="mb-4">
        <label htmlFor="ehr-file" className="block text-gray-700 text-sm font-bold mb-2">
          Select EHR File:
        </label>
        <input type="file" id="ehr-file" onChange={handleFileChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline" />
      </div>
      <div className="mb-4">
        <label className="block text-gray-700 text-sm font-bold mb-2">Data Preview:</label>
        <textarea value={previewData} rows="5" className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline bg-gray-50" readOnly />
      </div>
      <div className="mb-4">
        <label className="inline-flex items-center">
          <input type="checkbox" className="form-checkbox h-5 w-5 text-gray-600" />
          <span className="ml-2 text-gray-700">Anonymize Data</span>
        </label>
      </div>
      <button className="bg-gray-500 hover:bg-gray-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline">Submit</button>
    </div>
  );
}

