function TrialMatchPrototype() {
  const [view, setView] = useState('upload'); // 'upload', 'loading', 'results'
  const [loadingMessage, setLoadingMessage] = useState('Analyzing Patient Record...');
  const [selectedTrial, setSelectedTrial] = useState(null);

  const handleFindTrials = () => {
    setView('loading');
    setTimeout(() => setLoadingMessage('Extracting eligibility criteria using NLP...'), 1000);
    setTimeout(() => setLoadingMessage('Matching against 1,248 trials in AU...'), 2000);
    setTimeout(() => {
      setView('results');
    }, 3500);
  };

  const openModal = (trial) => setSelectedTrial(trial);
  const closeModal = () => setSelectedTrial(null);

  const renderConfidenceBadge = (score) => {
    let bgColor, textColor;
    if (score >= 90) {
      bgColor = 'bg-green-100';
      textColor = 'text-green-800';
    } else if (score >= 75) {
      bgColor = 'bg-yellow-100';
      textColor = 'text-yellow-800';
    } else {
      bgColor = 'bg-orange-100';
      textColor = 'text-orange-800';
    }
    return (
      <span className={`px-3 py-1 text-sm font-medium rounded-full ${bgColor} ${textColor}`}>
        {score}% Match
      </span>
    );
  };

  const renderCriteriaIcon = (matchStatus) => {
      if (matchStatus === true) return <CheckIcon />;
      if (matchStatus === false) return <XIcon />;
      return <QuestionMarkIcon />;
  };

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-800">
      {/* Header */}
      <header className="bg-white shadow-sm border-b border-slate-200 sticky top-0 z-20">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <svg className="h-8 w-8 text-blue-600" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M12 2L2 7V17L12 22L22 17V7L12 2Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
              <path d="M2 7L12 12L22 7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
              <path d="M12 12V22" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
            <h1 className="text-xl font-bold text-slate-900">TrialMatch AI</h1>
          </div>
          <div className="flex items-center gap-6">
              <nav className="flex gap-4">
                  <a href="#" className="text-sm font-semibold text-blue-600 border-b-2 border-blue-600 pb-1">Dashboard</a>
                  <a href="#" className="text-sm font-medium text-slate-500 hover:text-blue-600 transition">Patients</a>
                  <a href="#" className="text-sm font-medium text-slate-500 hover:text-blue-600 transition">Trials</a>
              </nav>
              <div className="flex items-center gap-3">
                  <img className="h-9 w-9 rounded-full object-cover" src="https://i.pravatar.cc/150?u=dr_vance" alt="Dr. Eleanor Vance" />
                  <div>
                      <p className="text-sm font-semibold">Dr. Eleanor Vance</p>
                      <p className="text-xs text-slate-500">Oncologist</p>
                  </div>
              </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10">
        {view === 'upload' && (
          <div className="max-w-2xl mx-auto bg-white p-8 rounded-xl shadow-md border border-slate-200 text-center">
            <div className="mb-6">
                <h2 className="text-2xl font-bold text-slate-900">Find Clinical Trials for {mockPatient.name}</h2>
                <p className="text-slate-500 mt-2">Current Diagnosis: {mockPatient.condition}</p>
            </div>
            <div className="bg-slate-50 border-2 border-dashed border-slate-300 rounded-lg p-10 flex flex-col items-center">
                <svg className="h-12 w-12 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1}>
                    <path strokeLinecap="round" strokeLinejoin="round" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                </svg>
                <p className="mt-4 font-semibold text-slate-700">Patient EHR is ready for analysis.</p>
                <p className="text-sm text-slate-500 mt-1">Click below to begin the AI matching process.</p>
            </div>
            <button 
              onClick={handleFindTrials}
              className="mt-8 w-full bg-blue-600 text-white font-semibold py-3 px-6 rounded-lg hover:bg-blue-700 focus:outline-none focus:ring-4 focus:ring-blue-300 transition-all duration-300 transform hover:scale-105"
            >
              Analyze & Find Trials
            </button>
          </div>
        )}

        {view === 'loading' && (
          <div className="text-center py-20">
            <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-blue-600 mx-auto"></div>
            <p className="mt-6 text-lg font-semibold text-slate-700">{loadingMessage}</p>
            <p className="text-slate-500">This may take a few moments...</p>
          </div>
        )}

        {view === 'results' && (
          <div>
            <div className="mb-6">
              <h2 className="text-3xl font-bold text-slate-900">Matching Trials for {mockPatient.name}</h2>
              <p className="text-slate-600 mt-1">Found <span className="font-bold text-blue-600">{mockTrials.length} potential matches</span> based on the patient's record.</p>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              {mockTrials.map(trial => (
                <div key={trial.id} className="bg-white rounded-xl shadow-md border border-slate-200 p-6 hover:shadow-lg hover:-translate-y-1 transition-all duration-300">
                  <div className="flex justify-between items-start">
                    <h3 className="text-lg font-bold text-slate-900 pr-4">{trial.title}</h3>
                    {renderConfidenceBadge(trial.confidence)}
                  </div>
                  <div className="mt-4 flex items-center gap-6 text-sm text-slate-500">
                    <span className="font-semibold text-slate-700">{trial.id}</span>
                    <span className="bg-slate-100 px-2 py-0.5 rounded">Phase {trial.phase}</span>
                  </div>
                  <p className="mt-2 text-sm text-slate-600 flex items-start gap-2">
                    <svg className="h-4 w-4 text-slate-400 mt-0.5 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                    {trial.location}
                  </p>
                  <button 
                    onClick={() => openModal(trial)}
                    className="mt-6 w-full bg-white text-blue-600 font-semibold py-2 px-4 rounded-lg border-2 border-blue-600 hover:bg-blue-50 focus:outline-none focus:ring-2 focus:ring-blue-400 transition"
                  >
                    View Details & Eligibility
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      {/* Modal */}
      {selectedTrial && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-30 flex items-center justify-center p-4" onClick={closeModal}>
          <div className="bg-white rounded-xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto" onClick={e => e.stopPropagation()}>
            <div className="p-6 border-b border-slate-200 sticky top-0 bg-white">
                <div className="flex justify-between items-center">
                    <h3 className="text-xl font-bold text-slate-900">{selectedTrial.title}</h3>
                    <button onClick={closeModal} className="text-slate-400 hover:text-slate-600">&times;</button>
                </div>
                <p className="text-sm text-slate-500 mt-1">{selectedTrial.id}</p>
            </div>
            <div className="p-6">
              <h4 className="font-semibold text-slate-800">Summary</h4>
              <p className="mt-2 text-slate-600 text-sm">{selectedTrial.summary}</p>

              <h4 className="font-semibold text-slate-800 mt-6">Key Eligibility Criteria Match</h4>
              <p className="text-sm text-slate-500">Based on NLP analysis of the patient's record.</p>
              <ul className="mt-4 space-y-3">
                {selectedTrial.criteria.map((item, index) => (
                  <li key={index} className="flex items-start gap-3">
                    <div className="mt-0.5">{renderCriteriaIcon(item.match)}</div>
                    <span className="text-sm text-slate-700">{item.text}</span>
                  </li>
                ))}
              </ul>
            </div>
            <div className="p-6 bg-slate-50 border-t border-slate-200 sticky bottom-0 flex justify-end gap-3">
                <button onClick={closeModal} className="bg-white text-slate-700 font-semibold py-2 px-4 rounded-lg border border-slate-300 hover:bg-slate-100 transition">Close</button>
                <button className="bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 transition">Generate Pre-Screening Package</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

